import math
import sys

epsilon = 1e-9

def main():
    input_data = sys.stdin.read().strip().split()
    count = int(input_data[0])
    if count > 11:
        print(0)
        return
    data = []
    index = 1
    for _ in range(count):
        row = list(map(int, input_data[index:index+5]))
        data.append(row)
        index += 5

    result_indices = []

    for i in range(count):
        is_good = True
        for j in range(count):
            if j == i:
                continue
            for k in range(j + 1, count):
                if k == i:
                    continue
                vec1 = Vector(data[i], data[j])
                vec2 = Vector(data[i], data[k])
                angle_between = math.acos(vec1.prod(vec2) / (vec1.mag() * vec2.mag()))
                if angle_between < math.pi / 2 - epsilon:
                    is_good = False
                    break
            if not is_good:
                break
        if is_good:
            result_indices.append(i + 1)

    print(len(result_indices))
    for index in result_indices:
        print(index)

class Vector:
    def __init__(self, a, b):
        self.components = [b[i] - a[i] for i in range(5)]
    def mag(self):
        sum_squares = sum(c * c for c in self.components)
        return math.sqrt(sum_squares)
    def prod(self, v):
        return sum(self.components[i] * v.components[i] for i in range(5))

if __name__ == "__main__":
    main()

